//! Every syncable item field as its own last-writer-wins register.
//!
//! Format v3 (current, [`Fields`]): scalar fields are [`Lww`] registers; the
//! custom fields and the attachments are [`LwwMap`]s, one register per entry,
//! so concurrent edits of different custom fields both survive.
//!
//! Older shapes are still read and upgraded: [`FieldsV2`] (custom fields as
//! one register, no attachments) and [`FieldsV1`] (no `archived` either),
//! generated by the macro below from the list of fields each format had.

use password365_crypto::secret::SecretString;
use password365_model::{Attachment, CustomField, Item, ItemKind, VaultId};
use serde::{Deserialize, Serialize};

use crate::lww_map::{LwwMap, MapStamps};
use crate::{Hlc, Lww};

macro_rules! stamped_fields {
    (v1 { $($v1:tt)* } added { $($new:ident : $nty:ty => $($npath:ident).+;)* }) => {
        stamped_fields!(@current $($v1)* $($new : $nty => $($npath).+;)*);
        stamped_fields!(@legacy [$($new : $nty),*] $($v1)*);
    };
    (@legacy [$($new:ident : $nty:ty),*] $($name:ident : $ty:ty => $($path:ident).+;)*) => {
        /// [`FieldsV2`] as format v1 stored and sent them.
        #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
        pub struct FieldsV1 {
            $(
                #[doc = concat!("`", stringify!($($path).+), "`")]
                pub $name: Lww<$ty>,
            )*
        }

        /// [`StampsV2`] as format v1 stored and sent them.
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
        pub struct StampsV1 {
            $(
                #[doc = concat!("Stamp of `", stringify!($name), "`.")]
                pub $name: Hlc,
            )*
        }

        impl From<FieldsV1> for FieldsV2 {
            fn from(old: FieldsV1) -> Self {
                let zero = Hlc::zero(old.kind.stamp.device);
                Self {
                    $($name: old.$name,)*
                    $($new: Lww::new(<$nty>::default(), zero),)*
                }
            }
        }

        /// Drops the fields added later (tests and tools only: never stored).
        impl From<&FieldsV2> for FieldsV1 {
            fn from(current: &FieldsV2) -> Self {
                Self { $($name: current.$name.clone(),)* }
            }
        }

        /// Drops the stamps of fields added later (tests and tools only).
        impl From<StampsV2> for StampsV1 {
            fn from(current: StampsV2) -> Self {
                Self { $($name: current.$name,)* }
            }
        }

        impl From<StampsV1> for StampsV2 {
            fn from(old: StampsV1) -> Self {
                let zero = Hlc::zero(old.kind.device);
                Self {
                    $($name: old.$name,)*
                    $($new: zero,)*
                }
            }
        }
    };
    (@current $($name:ident : $ty:ty => $($path:ident).+;)*) => {
        /// Item fields as format v2 stored and sent them (read only: upgraded to [`Fields`]).
        #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
        pub struct FieldsV2 {
            $(
                #[doc = concat!("`", stringify!($($path).+), "`")]
                pub $name: Lww<$ty>,
            )*
        }

        /// Just the stamps of [`FieldsV2`] (what a deletion had seen).
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
        pub struct StampsV2 {
            $(
                #[doc = concat!("Stamp of `", stringify!($name), "`.")]
                pub $name: Hlc,
            )*
        }

        impl FieldsV2 {
            /// All of `item`'s fields, written at `stamp`.
            #[must_use]
            pub fn capture(item: &Item, stamp: Hlc) -> Self {
                Self { $($name: Lww::new(item.$($path).+.clone(), stamp),)* }
            }

            /// Restamps the fields that differ in `item`; returns whether any did.
            pub fn record(&mut self, item: &Item, stamp: Hlc) -> bool {
                let mut changed = false;
                $(changed |= self.$name.set(item.$($path).+.clone(), stamp);)*
                changed
            }

            /// Field-by-field newest write.
            #[must_use]
            pub fn merge(&self, other: &Self) -> Self {
                Self { $($name: self.$name.merge(&other.$name),)* }
            }

            /// Copies the values into `item`.
            pub fn write_to(&self, item: &mut Item) {
                $(item.$($path).+ = self.$name.value.clone();)*
            }

            /// Replaces every stamp (values unchanged).
            pub fn restamp(&mut self, stamps: &StampsV2) {
                $(self.$name.stamp = stamps.$name;)*
            }

            /// The stamps alone.
            #[must_use]
            pub fn stamps(&self) -> StampsV2 {
                StampsV2 { $($name: self.$name.stamp,)* }
            }
        }

        impl StampsV2 {
            /// Every field at `stamp`.
            #[must_use]
            pub fn uniform(stamp: Hlc) -> Self {
                Self { $($name: stamp,)* }
            }

            /// Field-by-field maximum.
            #[must_use]
            pub fn max(&self, other: &Self) -> Self {
                Self { $($name: self.$name.max(other.$name),)* }
            }

            /// `true` when any field was written after the matching one in `other`.
            #[must_use]
            pub fn any_newer_than(&self, other: &Self) -> bool {
                false $(|| self.$name > other.$name)*
            }

            /// The newest stamp of all fields.
            #[must_use]
            pub fn latest(&self) -> Hlc {
                let all = [$(self.$name),*];
                all.into_iter().fold(all[0], Hlc::max)
            }
        }
    };
}

stamped_fields! {
    v1 {
        kind: ItemKind => kind;
        vault_id: VaultId => vault_id;
        title: String => overview.title;
        username: Option<String> => overview.username;
        urls: Vec<String> => overview.urls;
        tags: Vec<String> => overview.tags;
        favorite: bool => overview.favorite;
        password: Option<SecretString> => details.password;
        notes: Option<SecretString> => details.notes;
        totp: Option<SecretString> => details.totp;
        custom_fields: Vec<CustomField> => details.custom_fields;
    }
    added {
        archived: bool => overview.archived;
    }
}

/// Declares the format v3 fields: scalar registers and keyed maps.
macro_rules! current_fields {
    (
        scalars { $($s:ident : $sty:ty => $($sp:ident).+;)* }
        maps { $($m:ident : $mty:ty => $($mp:ident).+;)* }
    ) => {
        /// Item fields (format v3), each with the stamp of its last write.
        #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
        pub struct Fields {
            $(
                #[doc = concat!("`", stringify!($($sp).+), "`")]
                pub $s: Lww<$sty>,
            )*
            $(
                #[doc = concat!("`", stringify!($($mp).+), "`, entry by entry")]
                pub $m: LwwMap<$mty>,
            )*
        }

        /// The newest stamp of each field (what a deletion had seen; for a
        /// map, its newest entry).
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
        pub struct Stamps {
            $(
                #[doc = concat!("Stamp of `", stringify!($s), "`.")]
                pub $s: Hlc,
            )*
            $(
                #[doc = concat!("Newest stamp in `", stringify!($m), "`.")]
                pub $m: Hlc,
            )*
        }

        /// Each map's entry stamps (stored next to the item, which has the values).
        #[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
        pub struct EntryStamps {
            $(
                #[doc = concat!("Entries of `", stringify!($m), "`.")]
                pub $m: MapStamps,
            )*
        }

        impl Fields {
            /// All of `item`'s fields, written at `stamp`.
            #[must_use]
            pub fn capture(item: &Item, stamp: Hlc) -> Self {
                Self {
                    $($s: Lww::new(item.$($sp).+.clone(), stamp),)*
                    $($m: LwwMap::capture(&item.$($mp).+, stamp),)*
                }
            }

            /// Restamps the fields (and entries) that differ in `item`; returns whether any did.
            pub fn record(&mut self, item: &Item, stamp: Hlc) -> bool {
                let mut changed = false;
                $(changed |= self.$s.set(item.$($sp).+.clone(), stamp);)*
                $(changed |= self.$m.set(&item.$($mp).+, stamp);)*
                changed
            }

            /// Field-by-field (and entry-by-entry) newest write.
            #[must_use]
            pub fn merge(&self, other: &Self) -> Self {
                Self {
                    $($s: self.$s.merge(&other.$s),)*
                    $($m: self.$m.merge(&other.$m),)*
                }
            }

            /// Copies the values into `item`.
            pub fn write_to(&self, item: &mut Item) {
                $(item.$($sp).+ = self.$s.value.clone();)*
                $(item.$($mp).+ = self.$m.values();)*
            }

            /// Replaces every stamp (values unchanged); map entries all get their map's stamp.
            pub fn restamp(&mut self, stamps: &Stamps) {
                $(self.$s.stamp = stamps.$s;)*
                $(self.$m.restamp(stamps.$m);)*
            }

            /// The newest stamp of each field.
            #[must_use]
            pub fn stamps(&self) -> Stamps {
                Stamps {
                    $($s: self.$s.stamp,)*
                    $($m: self.$m.latest(),)*
                }
            }

            /// The maps' entry stamps.
            #[must_use]
            pub fn entry_stamps(&self) -> EntryStamps {
                EntryStamps { $($m: self.$m.stamps(),)* }
            }

            /// Rebuilds the fields of a stored `item` from its stamps.
            #[must_use]
            pub fn from_parts(item: &Item, stamps: &Stamps, entries: &EntryStamps) -> Self {
                Self {
                    $($s: Lww::new(item.$($sp).+.clone(), stamps.$s),)*
                    $($m: LwwMap::with_stamps(&item.$($mp).+, &entries.$m, stamps.$m),)*
                }
            }
        }

        impl Stamps {
            /// Every field at `stamp`.
            #[must_use]
            pub fn uniform(stamp: Hlc) -> Self {
                Self { $($s: stamp,)* $($m: stamp,)* }
            }

            /// Field-by-field maximum.
            #[must_use]
            pub fn max(&self, other: &Self) -> Self {
                Self { $($s: self.$s.max(other.$s),)* $($m: self.$m.max(other.$m),)* }
            }

            /// `true` when any field was written after the matching one in `other`.
            #[must_use]
            pub fn any_newer_than(&self, other: &Self) -> bool {
                false $(|| self.$s > other.$s)* $(|| self.$m > other.$m)*
            }

            /// The newest stamp of all fields.
            #[must_use]
            pub fn latest(&self) -> Hlc {
                let all = [$(self.$s,)* $(self.$m,)*];
                all.into_iter().fold(all[0], Hlc::max)
            }
        }

        /// Format v2 fields upgrade: the custom fields become one entry each
        /// at their register's stamp; no attachments yet.
        impl From<FieldsV2> for Fields {
            fn from(old: FieldsV2) -> Self {
                let zero = Hlc::zero(old.kind.stamp.device);
                Self {
                    $($s: old.$s,)*
                    custom_fields: LwwMap::capture(&old.custom_fields.value, old.custom_fields.stamp),
                    attachments: LwwMap::empty(zero),
                }
            }
        }

        impl From<StampsV2> for Stamps {
            fn from(old: StampsV2) -> Self {
                Self {
                    $($s: old.$s,)*
                    custom_fields: old.custom_fields,
                    attachments: Hlc::zero(old.kind.device),
                }
            }
        }

        /// Back to format v2 (tests and tools only: drops attachments and
        /// per-field stamps).
        impl From<&Fields> for FieldsV2 {
            fn from(current: &Fields) -> Self {
                Self {
                    $($s: current.$s.clone(),)*
                    custom_fields: Lww::new(current.custom_fields.values(), current.custom_fields.latest()),
                }
            }
        }

        impl From<Stamps> for StampsV2 {
            fn from(current: Stamps) -> Self {
                Self { $($s: current.$s,)* custom_fields: current.custom_fields }
            }
        }
    };
}

current_fields! {
    scalars {
        kind: ItemKind => kind;
        vault_id: VaultId => vault_id;
        title: String => overview.title;
        username: Option<String> => overview.username;
        urls: Vec<String> => overview.urls;
        tags: Vec<String> => overview.tags;
        favorite: bool => overview.favorite;
        password: Option<SecretString> => details.password;
        notes: Option<SecretString> => details.notes;
        totp: Option<SecretString> => details.totp;
        archived: bool => overview.archived;
    }
    maps {
        custom_fields: CustomField => details.custom_fields;
        attachments: Attachment => details.attachments;
    }
}

/// Format v1 fields upgrade through format v2.
impl From<FieldsV1> for Fields {
    fn from(old: FieldsV1) -> Self {
        FieldsV2::from(old).into()
    }
}

impl From<StampsV1> for Stamps {
    fn from(old: StampsV1) -> Self {
        StampsV2::from(old).into()
    }
}

/// Back to format v1 (tests and tools only).
impl From<&Fields> for FieldsV1 {
    fn from(current: &Fields) -> Self {
        Self::from(&FieldsV2::from(current))
    }
}

impl From<Stamps> for StampsV1 {
    fn from(current: Stamps) -> Self {
        StampsV2::from(current).into()
    }
}

#[cfg(test)]
mod tests {
    use password365_model::{ItemDetails, ItemOverview, Timestamp};

    use super::*;
    use crate::DeviceId;

    fn at(wall_ms: i64) -> Hlc {
        Hlc {
            wall_ms,
            counter: 0,
            device: DeviceId::from_bytes([1; 16]),
        }
    }

    fn item() -> Item {
        Item::new(
            VaultId::new(),
            ItemKind::Login,
            ItemOverview::new("Mail").unwrap().with_username("me"),
            ItemDetails::with_password("p1".into()),
            Timestamp::from_millis(1),
        )
    }

    #[test]
    fn capture_and_write_back_round_trip() {
        let original = item();
        let fields = Fields::capture(&original, at(1));
        let mut copy = original.clone();
        copy.overview.title = "changed".into();
        copy.details.password = None;
        fields.write_to(&mut copy);
        assert_eq!(copy, original);
    }

    #[test]
    fn record_restamps_only_changed_fields() {
        let mut it = item();
        let mut fields = Fields::capture(&it, at(1));
        assert!(!fields.record(&it, at(2)));
        it.overview.title = "Inbox".into();
        assert!(fields.record(&it, at(3)));
        assert_eq!(fields.title, Lww::new("Inbox".to_owned(), at(3)));
        assert_eq!(fields.username.stamp, at(1));
        assert_eq!(fields.stamps().latest(), at(3));
    }

    #[test]
    fn merge_keeps_the_newest_write_per_field() {
        let it = item();
        let base = Fields::capture(&it, at(1));
        let mut a = base.clone();
        let mut b = base;
        let mut edited = it.clone();
        edited.overview.title = "A title".into();
        a.record(&edited, at(2));
        let mut edited = it;
        edited.overview.username = Some("b-user".into());
        b.record(&edited, at(3));
        let merged = a.merge(&b);
        assert_eq!(merged.title.value, "A title");
        assert_eq!(merged.username.value.as_deref(), Some("b-user"));
        assert_eq!(merged, b.merge(&a));
    }

    #[test]
    fn format_v1_fields_gain_the_new_ones_at_the_zero_stamp() {
        let it = item();
        let current = Fields::capture(&it, at(4));
        let old = FieldsV1::from(&current);
        let upgraded = Fields::from(old);
        assert_eq!(upgraded.archived, Lww::new(false, at(0)));
        assert_eq!(upgraded.title, current.title);
        let mut archived = it;
        archived.overview.archived = true;
        let mut newer = upgraded.clone();
        newer.record(&archived, at(5));
        assert!(upgraded.merge(&newer).archived.value, "any real write wins");

        let stamps = current.stamps();
        let old = StampsV1::from(stamps);
        assert_eq!(Stamps::from(old).archived, at(0));
    }

    #[test]
    fn stamps_compare_field_by_field() {
        let it = item();
        let old = Fields::capture(&it, at(1)).stamps();
        let mut newer = Fields::capture(&it, at(1));
        let mut edited = it;
        edited.overview.favorite = true;
        newer.record(&edited, at(5));
        let newer = newer.stamps();
        assert!(newer.any_newer_than(&old));
        assert!(!old.any_newer_than(&newer));
        assert!(!old.any_newer_than(&old));
        assert_eq!(old.max(&newer), newer);
    }
}
